const uniq=a=>[...new Set(a.filter(Boolean))].sort();
async function fetchSheet(id){
const url=`https://docs.google.com/spreadsheets/d/${id}/gviz/tq?tqx=out:json&headers=1&_=${Date.now()}`;
const res=await fetch(url);const txt=await res.text();
const s=txt.indexOf('{'),e=txt.lastIndexOf('}');
const j=JSON.parse(txt.slice(s,e+1));
if(j.status!=='ok')throw new Error(j.errors||'gviz error');
const labels=j.table.cols.map(c=>c.label);
return j.table.rows.map(r=>{const o={};labels.forEach((lb,i)=>{const c=r.c[i];o[lb]=c?(c.v??'') :''});return o});
}
function setDot(el,mode){document.getElementById(el).className='dot '+mode}
async function loadLive(manual){
try{
document.getElementById('crmStatus').textContent='讀取中…';
document.getElementById('invStatus').textContent='讀取中…';
const [c,i]=await Promise.all([fetchSheet(CRM_ID),fetchSheet(INV_ID)]);
crm=c.filter(r=>String(r['客戶編號']||'').startsWith('C'));
inv=i.filter(r=>String(r['商品編號']||'').startsWith('P'));
lastUpdate=new Date();
document.getElementById('crmStatus').textContent=`即時連線成功，共 ${crm.length} 筆`;
document.getElementById('invStatus').textContent=`即時連線成功，共 ${inv.length} 筆`;
setDot('dotCrm','live');setDot('dotInv','live');
}catch(err){
if(!crm.length&&window.CRM_DATA)crm=window.CRM_DATA;
if(!inv.length&&window.INV_DATA)inv=window.INV_DATA;
document.getElementById('crmStatus').textContent='即時讀取失敗，已用內建快取（可按開啟試算表確認共用權限）';
document.getElementById('invStatus').textContent='即時讀取失敗，已用內建快取';
setDot('dotCrm','cache');setDot('dotInv','cache');
if(!lastUpdate)lastUpdate=new Date();
}
document.getElementById('updateTime').textContent='更新時間：'+lastUpdate.toLocaleString('zh-TW',{hour12:false});
buildOptions();applyFilters();applyInvFilters();renderKpis();
if(manual)flash();
}
function flash(){const el=document.getElementById('updateTime');el.style.color='#e34d4d';setTimeout(()=>el.style.color='',800)}
function setAuto(){if(timer)clearInterval(timer);const s=+document.getElementById('autoRef').value;if(s>0)timer=setInterval(()=>loadLive(false),s*1000)}
function switchTab(t){tab=t;
document.getElementById('sideCrm').classList.toggle('active',t==='crm');
document.getElementById('sideInv').classList.toggle('active',t==='inv');
document.getElementById('panelCrm').style.display=t==='crm'?'block':'none';
document.getElementById('panelInv').style.display=t==='inv'?'block':'none';
renderKpis()}
const PALETTE=['#e34d4d','#f7b500','#3aa7a3','#6c8cff','#f78d8d','#2ecc71','#9b59b6'];
function countBy(rows,key){const m={};rows.forEach(r=>{const k=String(r[key]||'未填')||'未填';m[k]=(m[k]||0)+1});return Object.entries(m).sort((a,b)=>b[1]-a[1])}
function pieCard(title,pairs){
const total=pairs.reduce((s,p)=>s+p[1],0)||1;let acc=0;
const stops=pairs.map((p,i)=>{const from=(acc/total*100).toFixed(1);acc+=p[1];const to=(acc/total*100).toFixed(1);return `${PALETTE[i%PALETTE.length]} ${from}% ${to}%`});
const legend=pairs.map((p,i)=>`<div><span class="sw" style="background:${PALETTE[i%PALETTE.length]}"></span>${p[0]}：${p[1].toLocaleString()}（${(p[1]/total*100).toFixed(1)}%）</div>`).join('');
return `<div class="chart-card"><h3>${title}（圓餅圖・即時）</h3><div class="chart-body"><div class="pie" style="background:conic-gradient(${stops.join(',')})"></div><div class="legend">${legend||'無資料'}</div></div></div>`}
function barCard(title,pairs,isMoney){
const max=pairs.length?pairs[0][1]:1;
const rows=pairs.map((p,i)=>{const w=Math.max(2,Math.round(p[1]/max*100));const v=isMoney?fmt(p[1]):p[1].toLocaleString();return `<div class="bar-row"><div>${p[0]}</div><div class="bar-track"><div class="bar-fill" style="width:${w}%;background:${PALETTE[i%PALETTE.length]}"></div></div><div class="bar-val">${v}</div></div>`}).join('');
return `<div class="chart-card"><h3>${title}（長條圖・即時）</h3>${rows||'無資料'}</div>`}
function renderCharts(){
const el=document.getElementById('charts');if(!el)return;
if(tab==='crm'){
el.innerHTML=pieCard('客戶等級分佈',countBy(crm,'客戶等級'))+barCard('流失風險人數',countBy(crm,'流失風險'))+barCard('產業客戶數',countBy(crm,'產業'));
}else{
const amtByWh={};inv.forEach(r=>{const k=r['倉庫']||'未填';amtByWh[k]=(amtByWh[k]||0)+num(r['庫存金額'])});
const whPairs=Object.entries(amtByWh).sort((a,b)=>b[1]-a[1]);
el.innerHTML=pieCard('缺貨風險分佈',countBy(inv,'缺貨風險'))+barCard('商品類別 SKU 數',countBy(inv,'商品類別'))+barCard('各倉庫存金額（元）',whPairs,true);
}}
function renderKpis(){
const el=document.getElementById('kpis');
if(tab==='crm'){
const rev=crm.reduce((s,r)=>s+num(r['累積營收']),0);
const hi=crm.filter(r=>r['流失風險']==='高').length;
const bad=crm.filter(r=>String(r['資料檢查']||'').trim()!=='').length;
const vip=crm.filter(r=>r['客戶等級']==='VIP').length;
el.innerHTML=`<div class="kpi"><div class="n">${crm.length.toLocaleString()}</div><div class="l">CRM 總客戶數（即時）</div></div><div class="kpi"><div class="n">${fmt(rev)}</div><div class="l">累積營收總額（元，即時加總）</div></div><div class="kpi"><div class="n">${hi}</div><div class="l">高流失風險（即時）</div></div><div class="kpi"><div class="n">${bad} / VIP ${vip}</div><div class="l">資料異常 / VIP 數</div></div>`;
}else{
const amt=inv.reduce((s,r)=>s+num(r['庫存金額']),0);
const hi=inv.filter(r=>r['缺貨風險']==='高').length;
const need=inv.filter(r=>num(r['建議採購量'])>0).length;
el.innerHTML=`<div class="kpi"><div class="n">${inv.length.toLocaleString()}</div><div class="l">庫存總 SKU（即時）</div></div><div class="kpi"><div class="n">${fmt(amt)}</div><div class="l">庫存總金額（元，即時加總）</div></div><div class="kpi"><div class="n">${hi}</div><div class="l">高缺貨風險（即時）</div></div><div class="kpi"><div class="n">${need}</div><div class="l">建議採購 &gt; 0（即時）</div></div>`;
}
renderCharts()}
function buildOptions(){
const fi=document.getElementById('fInd');const cur=fi.value;fi.innerHTML='<option value="">全部</option>';uniq(crm.map(r=>r['產業'])).forEach(v=>{const o=document.createElement('option');o.textContent=v;fi.appendChild(o)});fi.value=cur;
const w=document.getElementById('gWh');const cw=w.value;w.innerHTML='<option value="">全部</option>';uniq(inv.map(r=>r['倉庫'])).forEach(v=>{const o=document.createElement('option');o.textContent=v;w.appendChild(o)});w.value=cw;
const c=document.getElementById('gCat');const cc=c.value;c.innerHTML='<option value="">全部</option>';uniq(inv.map(r=>r['商品類別'])).forEach(v=>{const o=document.createElement('option');o.textContent=v;c.appendChild(o)});c.value=cc;
}
function sortRows(st){st.rows.sort((a,b)=>{const x=a[st.sortK],y=b[st.sortK];const xn=num(x),yn=num(y);const bothNum=String(x)!==''&&String(y)!==''&&!isNaN(+String(x).replace(/,/g,''))&&!isNaN(+String(y).replace(/,/g,''));const c=bothNum?(xn-yn):String(x??'').localeCompare(String(y??''),'zh-Hant');return c*st.sortD})}
function bindSort(tid,st,render){document.querySelectorAll('#'+tid+' th[data-k]').forEach(th=>th.onclick=()=>{const k=th.dataset.k;if(st.sortK===k)st.sortD*=-1;else{st.sortK=k;st.sortD=1}sortRows(st);render()})}
function riskTag(v){if(v==='高')return '<span class="tag tag-high">高</span>';if(v==='中')return '<span class="tag tag-mid">中</span>';if(v==='低')return '<span class="tag tag-low">低</span>';return v||''}
function applyFilters(){
const kw=document.getElementById('fKw').value.trim().toLowerCase();
const ind=document.getElementById('fInd').value,lv=document.getElementById('fLevel').value,rk=document.getElementById('fRisk').value;
const bad=document.getElementById('fBad').checked;
f.rows=crm.filter(r=>{
if(ind&&r['產業']!==ind)return false;
if(lv&&r['客戶等級']!==lv)return false;
if(rk&&r['流失風險']!==rk)return false;
if(bad&&!String(r['資料檢查']||'').trim())return false;
if(kw&&!(String(r['客戶編號']+r['客戶名稱']).toLowerCase().includes(kw)))return false;
return true});
sortRows(f);f.pg=0;renderCrm();
}
function resetFilters(){['fKw','fInd','fLevel','fRisk'].forEach(id=>document.getElementById(id).value='');document.getElementById('fBad').checked=false;applyFilters()}
function renderCrm(){
const ps=+document.getElementById('pageSize').value||20;
const pages=Math.max(1,Math.ceil(f.rows.length/ps));f.pg=Math.min(Math.max(0,f.pg),pages-1);
const slice=f.rows.slice(f.pg*ps,f.pg*ps+ps);
const tb=document.querySelector('#crmTable tbody');tb.innerHTML='';
slice.forEach(r=>{
const tr=document.createElement('tr');if(String(r['資料檢查']||'').trim())tr.className='warn-row';
const lv=r['客戶等級']==='VIP'?'<span class="tag tag-vip">VIP</span>':(r['客戶等級']||'');
tr.innerHTML=`<td>${r['最後交易日']||''}<br><span style="color:#999">${r['地區']||''}</span></td><td><b>${r['產業']||''}</b><br>${r['客戶編號']||''}<br>${r['客戶名稱']||''}</td><td>${r['交易次數']||''}</td><td>${fmt(num(r['累積營收']))}</td><td>${fmt(num(r['平均客單價']))}</td><td>R:${r['R值(Recency)']??''} F:${r['F值(Frequency)']??''} M:${r['M值(Monetary)']??''}</td><td>${lv}</td><td>${riskTag(r['流失風險'])}</td><td>${r['負責業務']||''}</td><td>${r['資料檢查']?'<span class="err">'+r['資料檢查']+'</span>':''}</td>`;
tb.appendChild(tr)});
document.getElementById('pgInfo').textContent=`第 ${f.pg+1} / ${pages} 頁，共 ${f.rows.length} 筆`;
}
function page(d){f.pg+=d;renderCrm()}
function applyInvFilters(){
const kw=document.getElementById('gKw').value.trim().toLowerCase();
const wh=document.getElementById('gWh').value,cat=document.getElementById('gCat').value,rk=document.getElementById('gRisk').value;
const need=document.getElementById('gNeed').checked;
g.rows=inv.filter(r=>{
if(wh&&r['倉庫']!==wh)return false;
if(cat&&r['商品類別']!==cat)return false;
if(rk&&r['缺貨風險']!==rk)return false;
if(need&&num(r['建議採購量'])<=0)return false;
if(kw&&!(String(r['商品編號']+r['商品名稱']).toLowerCase().includes(kw)))return false;
return true});
sortRows(g);g.pg=0;renderInv();
}
function resetInvFilters(){['gKw','gWh','gCat','gRisk'].forEach(id=>document.getElementById(id).value='');document.getElementById('gNeed').checked=false;applyInvFilters()}
function renderInv(){
const ps=20,pages=Math.max(1,Math.ceil(g.rows.length/ps));g.pg=Math.min(Math.max(0,g.pg),pages-1);
const slice=g.rows.slice(g.pg*ps,g.pg*ps+ps);
const tb=document.querySelector('#invTable tbody');tb.innerHTML='';
slice.forEach(r=>{
const tr=document.createElement('tr');if(r['缺貨風險']==='高')tr.className='warn-row';
tr.innerHTML=`<td>${r['最後進貨日']||''}<br><span style="color:#999">${r['供應商']||''}</span></td><td><b>${r['商品類別']||''}</b><br>${r['商品編號']||''}<br>${r['商品名稱']||''}</td><td>${r['倉庫']||''}</td><td>${r['目前庫存']??''}</td><td>${r['安全庫存']??''}</td><td>${r['近30天銷量']??''}</td><td>${fmt(num(r['庫存金額']))}</td><td>${riskTag(r['缺貨風險'])}</td><td><b>${r['建議採購量']??''}</b></td><td>${r['備註']?'<span class="err">'+r['備註']+'</span>':''}</td>`;
tb.appendChild(tr)});
document.getElementById('pgInfoInv').textContent=`第 ${g.pg+1} / ${pages} 頁，共 ${g.rows.length} 筆`;
}
function pageInv(d){g.pg+=d;renderInv()}
bindSort('crmTable',f,renderCrm);bindSort('invTable',g,renderInv);
loadLive(false);setAuto();
